  'midnight.connector.provingServerBodyDefault': '{domain} le pidió a tu billetera que genere la prueba criptográfica de una transacción. Gero Cloud solo genera pruebas de transacciones que crea la propia billetera, así que la billetera buscó un generador local de pruebas en {url} y no obtuvo respuesta.',
  'midnight.connector.provingServerBodyLocal': '{domain} le pidió a tu billetera que genere la prueba criptográfica de una transacción, pero tu generador local de pruebas en {url} no respondió.',
  'midnight.connector.provingServerBodyZkpaas': '{domain} le pidió a tu billetera que genere la prueba criptográfica de una transacción, pero Arkhia zkPaaS no respondió. Revisa la clave de API y el endpoint en la configuración de pruebas criptográficas.',
