  'midnight.connector.provingServerRetry': 'Reintentar',
  'midnight.consent.title': 'Privacidad en la generación de pruebas',
  'midnight.consent.subtitle': 'Elige quién recibe los datos de entrada de tus pruebas',
  'midnight.consent.intro': 'Los envíos de Midnight necesitan una prueba. Esto incluye los envíos de tokens públicos que gastan DUST, los envíos de tokens privados y las transferencias que apruebas para sitios conectados. Un generador de pruebas remoto recibe los datos de entrada necesarios para crearla.',
  'midnight.consent.whatGeroSees': 'Qué ve Gero Cloud',
  'midnight.consent.whatGeroSeesBody': 'Gero Cloud recibe los datos de entrada de prueba de cada envío que pasa por él, incluidas las notas de comisión de DUST y las notas de tokens privados. Estos datos pueden incluir material de clave de las notas que se gastan, así que quien opera el generador de pruebas también podría gastarlas. Cualquiera que pueda leerlos podría vincular las notas y la billetera que paga la comisión con esa transacción.',
  'midnight.consent.whatWeDoNot': 'Lo que no hacemos',
  'midnight.consent.whatWeDoNotBody': 'Gero Cloud no registra ni almacena los datos de entrada de prueba. Las solicitudes llevan el token de sesión de Gero de este dispositivo y pasan por Cloudflare, donde termina la conexión cifrada antes de llegar a Gero.',
  'midnight.consent.localOption': '¿Prefieres ejecutar tu propio generador de pruebas?',
  'midnight.consent.localOptionBody': 'Ejecuta el servidor de pruebas oficial de Midnight en esta computadora y Gero generará las pruebas ahí. Tus datos de entrada de prueba se quedan en esta computadora. Configúralo en Configuración.',
  'midnight.consent.acknowledge': 'Permito que Gero Cloud reciba los datos de entrada de prueba de los envíos que usen Gero Cloud. Entiendo que estos datos pueden incluir material de clave de las notas que se gastan y revelar vínculos entre las notas, quien paga la comisión y la transacción.',
  'midnight.consent.acceptCloud': 'Usar Gero Cloud',
  'midnight.consent.useLocalInstead': 'Usar un generador local de pruebas',
  'midnight.consent.cancel': 'Cancelar',
  'midnight.consent.zkpaasWhatSees': 'Qué ve Arkhia zkPaaS',
  'midnight.consent.zkpaasWhatSeesBody': 'Arkhia zkPaaS recibe los datos de entrada de prueba de cada envío que pasa por él, incluidas las notas de comisión de DUST y las notas de tokens privados. Estos datos pueden incluir material de clave de las notas que se gastan. Gero no los recibe por esta vía. Cualquiera que pueda leerlos podría vincular las notas y la billetera que paga la comisión con esa transacción.',
  'midnight.consent.zkpaasWhatThisMeans': 'Qué significa esto',
  'midnight.consent.zkpaasWhatThisMeansBody': 'Arkhia ejecuta el generador de pruebas en hardware confidencial de Google Cloud y afirma que los datos del testigo criptográfico no se almacenan. Gero no puede verificarlo en cada solicitud, así que trata este servicio con la misma precaución que cualquier generador de pruebas remoto.',
  'midnight.consent.zkpaasAcknowledge': 'Permito que Arkhia zkPaaS reciba los datos de entrada de prueba de los envíos que usen Arkhia zkPaaS. Entiendo que estos datos pueden incluir material de clave de las notas que se gastan y revelar vínculos entre las notas, quien paga la comisión y la transacción.',
  'midnight.consent.zkpaasAccept': 'Usar Arkhia zkPaaS',
