  'midnight.proofServerPage.checkedAgo': 'Comprobado {time}',
  'midnight.proofServerPage.latencyMs': '{ms} ms de latencia',
  'midnight.proofServerPage.recentActivityTitle': 'Actividad reciente de generación de pruebas',
  'midnight.proofServerPage.provedIn': 'Prueba generada en {seconds} s',
  'midnight.proofServerPage.provingFailed': 'Error al generar la prueba',
  'midnight.proofServerPage.howItWorksTitle': 'Cómo se generan las pruebas',
  'midnight.proofServerPage.howItWorksBody': 'Las transacciones de Midnight que gastan DUST (comisiones) o tokens privados necesitan una prueba de conocimiento cero antes de enviarse. Esa prueba puede generarse en la nube o en tu propia computadora.',
  'midnight.proofServerPage.compareRemoteTitle': 'Gero Cloud',
  'midnight.proofServerPage.compareRemoteBody': 'Rápido y sin configuración. Los servidores de Gero generan la prueba, lo que requiere compartir los datos privados de la transacción necesarios para ese paso.',
  'midnight.proofServerPage.compareZkpaasTitle': 'Arkhia',
  'midnight.proofServerPage.compareZkpaasBody': 'Rápido, solo necesita una clave de API. El servicio zkPaaS de Arkhia genera la prueba dentro de la computación confidencial de Google Cloud y recibe los datos privados de la transacción en lugar de Gero.',
  'midnight.proofServerPage.compareLocalTitle': 'Local',
  'midnight.proofServerPage.compareLocalBody': 'Más lento de configurar, lo más privado. Esta computadora genera la prueba, así que Gero nunca recibe tus datos de entrada de prueba.',
  'midnight.proofServerPage.faqTitle': 'Preguntas frecuentes',
  'midnight.proofServerPage.consentNeededTitle': 'Permite este generador de pruebas',
  'midnight.proofServerPage.consentNeededBody': '{provider} recibe los datos de entrada de prueba de tus envíos y de las pruebas que piden los sitios conectados. Revisa lo que ve y permítelo antes de usarlo.',
  'midnight.proofServerPage.consentReview': 'Revisar y permitir',
  'midnight.proofServerPage.consentGiven': 'Permitiste que {provider} reciba datos de entrada de prueba.',
  'midnight.proofServerPage.faq1Q': '¿Qué es un generador de pruebas criptográficas?',
  'midnight.proofServerPage.faq1A': 'Genera la prueba de conocimiento cero que necesitan las transacciones de Midnight cuando gastan DUST (comisiones) o tokens privados, lo que cubre la mayoría de los envíos.',
  'midnight.proofServerPage.faq2Q': '¿Es seguro usar Gero Cloud?',
  'midnight.proofServerPage.faq2A': 'Gero Cloud recibe los datos de entrada de prueba de tu transacción a través de una conexión cifrada y no los almacena. Esos datos pueden incluir material de clave de las notas que se gastan, así que para la mayor privacidad y control, ejecuta un servidor de pruebas local.',
  'midnight.proofServerPage.faq3Q': '¿Por qué ejecutaría un generador local de pruebas?',
  'midnight.proofServerPage.faq3A': 'Un servidor de pruebas local mantiene tus datos de entrada de prueba en tu propia computadora, así que nunca llegan a la infraestructura de Gero.',
  'midnight.proofServerPage.faq4Q': '¿Esto afecta a las transacciones públicas (unshielded)?',
  'midnight.proofServerPage.faq4A': 'Sí. Las transferencias públicas de NIGHT pagan su comisión en DUST y gastar DUST necesita una prueba, así que también usan el generador de pruebas que elijas aquí.',
  'midnight.proofServerPage.faq5Q': '¿Qué es Arkhia zkPaaS?',
  'midnight.proofServerPage.faq5A': 'Un servicio alojado de generación de pruebas para el ecosistema de Midnight, que funciona detrás del gateway de API de Arkhia sobre la computación confidencial de Google Cloud (un entorno de ejecución confiable, así que los datos de la prueba permanecen cifrados incluso mientras se usan). Necesita una clave de API del panel de Arkhia. Como cualquier generador de pruebas remoto, recibe los datos privados de tu transacción para el paso de generación de la prueba; a diferencia de Gero Cloud, esos datos van a Arkhia y no a Gero.',
